function inBounds(p){
  return Math.abs(p.x)<=14.55&&Math.abs(p.z)<=11.55;
}
function collidesWithProps(p){
  const crates=[[-12,-2],[12,-2],[-12,4],[12,4],[-5,9],[5,-9]];
  for(const [x,z] of crates){if(Math.abs(p.x-x)<1.05&&Math.abs(p.z-z)<.95)return true}
  // Room shells and central console create solid surfaces.
  const solids=[[-8,-7,5,4],[8,-7,5,4],[-8,7,5,4],[8,7,5,4],[0,0,4,4]];
  for(const [x,z,w,d] of solids){if(Math.abs(p.x-x)<w/2+.38&&Math.abs(p.z-z)<d/2+.38)return true}
  return false;
}
function collide(pos,next){
  if(!inBounds(next))return true;
  if(collidesWithProps(next))return true;
  return false;
}
function tryMove(pos,delta){
  const nx=pos.clone();nx.x+=delta.x;if(!collide(pos,nx))pos.x=nx.x;
  const nz=pos.clone();nz.z+=delta.z;if(!collide(pos,nz))pos.z=nz.z;
}
function update(dt){if(running){let ax=(keys.d||keys.ArrowRight?1:0)-(keys.a||keys.ArrowLeft?1:0),az=(keys.s||keys.ArrowDown?1:0)-(keys.w||keys.ArrowUp?1:0);if(ax||az){const len=Math.hypot(ax,az);ax/=len;az/=len;tryMove(player.position,new THREE.Vector3(ax*dt*4.1,0,az*dt*4.1));player.rotation.y=Math.atan2(ax,az);animateCharacter(player,.48,t)}else animateCharacter(player,.08,t)}

