function updateJoystick(e){
  const r=joystick.getBoundingRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;
  let x=e.clientX-cx,y=e.clientY-cy,max=r.width*.34;
  const len=Math.hypot(x,y);if(len>max){x*=max/len;y*=max/len}
