let health=100,totalMistakes=0,revealUntil=0,emergencyUntil=0,taskStrikes=0;
function start(){running=true;completed=0;health=100;totalMistakes=0;taskStrikes=0;revealUntil=0;emergencyUntil=0;hitCooldown=0;document.getElementById('healthBar').style.width='100%';document.getElementById('mistakeBar').style.width='0%';document.getElementById('taskStrikes').textContent='STRIKE 0 / 3';menu.classList.add('hidden');document.getElementById('modal').classList.remove('show');player.position.set(-13.7,.1,-10.6);killer.position.set(13,.1,-10);tasks.forEach((o,i)=>{o.done=false;o.ring.visible=true});renderTasks();document.body.requestPointerLock?.()}
function registerMistake(){
  totalMistakes++;taskStrikes++;
  document.getElementById('mistakeBar').style.width=Math.min(100,totalMistakes/20*100)+'%';
  document.getElementById('taskStrikes').textContent=`STRIKE ${taskStrikes} / 3`;
  if(taskStrikes>=3){revealUntil=t+10;taskStrikes=0;document.getElementById('threat').textContent='● KONUM AÇIĞA ÇIKTI';document.getElementById('threat').style.color='#ff3555';setTimeout(()=>{if(running&&t>=revealUntil)document.getElementById('threat').textContent='● RADARDA YOK'},10000)}
}
function interact(){if(!running||near<0)return;
  const task=tasks[near];
  // V1 görev mini-prototipi: %25 hata olasılığıyla hata mekanizmasını test eder.
  if(Math.random()<.16){registerMistake();return}
  task.done=true;task.ring.visible=false;completed++;taskStrikes=0;document.getElementById('taskStrikes').textContent='STRIKE 0 / 3';renderTasks();
  if(completed>=tasks.length)finishTasks();
}
function finishTasks(){
  if(totalMistakes<20&&health>0&&hitCooldown>=0){
    // 0 ölüm koşulu henüz; en temiz sonuç secret armory yolunu açar.
    end(true,false,totalMistakes===0?'GİZLİ ARSENALİ AÇ':'Standart kaçış yolu açıldı');
  }else if(totalMistakes>=20){emergencyUntil=t+120;end(true,true,'Acil tahliye podları kilitlendi. 2 dakikada açılır.');}
}
function end(win,emergency=false,label=''){
  running=false;
  document.getElementById('endTitle').textContent=win?(emergency?'ACİL TAHLİYE':'GÜÇ SAĞLANDI'):'KATİL ZAFERİ';
  document.getElementById('endText').textContent=label||(win?'19 sistem çevrim içi. Ana çıkış açıldı.':'Anomali vardiyayı sonlandırdı.');
  document.getElementById('stamp').textContent=win?(emergency?'ACİL DURUM / 120 SANİYE':'SİNYAL / SONLANDI'):'SONUÇ / ÖLDÜN';document.getElementById('modal').classList.add('show')}

